async () => {
  const { execSync } = require('child_process');
  let results = '';

  // Test connectivity to hosts
  const hosts = ['google.com', 'cloudflare.com', 'github.com'];
  results += 'CONNECTIVITY TEST RESULTS\n';
  results += '========================\n';

  for (const host of hosts) {
    try {
      const output = execSync(`ping -c 4 ${host}`, { encoding: 'utf8', timeout: 10000 });
      results += `\n${host}:\n${output}\n`;
    } catch (error) {
      results += `\n${host}: FAILED - ${error.message}\n`;
    }
  }

  // Perform DNS resolution
  results += '\n\nDNS RESOLUTION RESULTS\n';
  results += '=====================\n';

  const domains = ['example.com', 'wikipedia.org', 'stackoverflow.com'];
  for (const domain of domains) {
    try {
      const output = execSync(`nslookup ${domain}`, { encoding: 'utf8', timeout: 5000 });
      results += `\n${domain}:\n${output}\n`;
    } catch (error) {
      results += `\n${domain}: FAILED - ${error.message}\n`;
    }
  }

  return results;
}
